//! Fixture conformance for the frozen canonical profile.
//!
//! The corpus is generated by `scripts/i03_canonical_vectors.py`, which is
//! written from the specification alone and shares no code with this crate.
//! Agreement here is therefore evidence about the specification: if the Rust
//! codec and the independent Python validator disagree, one of them is wrong and
//! the release gate fails.

use std::fs;
use std::path::PathBuf;

use puyudb_core::canon;
use puyudb_core::identity::{ArtifactId, BatchId, BranchId, EpochId, SpaceId, WriterEpoch};
use puyudb_core::profile::{self, Path, Record};
use serde_json::Value;

fn fixtures() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
        .join("tests")
        .join("fixtures")
        .join("canonical-v1")
}

fn load(name: &str) -> Value {
    let path = fixtures().join(name);
    let text = fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("cannot read {}: {error}", path.display()));
    serde_json::from_str(&text).expect("fixture is valid JSON")
}

fn entries<'a>(value: &'a Value, key: &str) -> &'a Vec<Value> {
    value[key]
        .as_array()
        .unwrap_or_else(|| panic!("{key} is an array"))
}

fn field<'a>(value: &'a Value, key: &str) -> &'a str {
    value[key]
        .as_str()
        .unwrap_or_else(|| panic!("{key} is a string"))
}

fn unhex(text: &str) -> Vec<u8> {
    assert!(text.len().is_multiple_of(2), "odd hex length");
    (0..text.len())
        .step_by(2)
        .map(|index| u8::from_str_radix(&text[index..index + 2], 16).expect("hex"))
        .collect()
}

fn hex(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        out.push_str(&format!("{byte:02x}"));
    }
    out
}

fn fixture_bytes(label: &str, width: usize) -> Vec<u8> {
    let digest = profile_sha256(format!("puyudb/canonical-v1/fixture/{label}").as_bytes());
    digest[..width].to_vec()
}

fn profile_sha256(bytes: &[u8]) -> [u8; 32] {
    use sha2::{Digest, Sha256};
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    hasher.finalize().into()
}

/// Total number of positive records the frozen profile requires vectors for.
const EXPECTED_VECTOR_COUNT: usize = 20;
/// Lower bounds so a generator regression cannot silently shrink the corpus.
const MIN_NEGATIVE_CASES: usize = 45;
const MIN_PATH_CASES: usize = 15;

#[test]
fn every_vector_decodes_validates_and_reencodes_canonically() {
    let vectors = load("vectors.json");
    let list = entries(&vectors, "vectors");
    assert_eq!(list.len(), EXPECTED_VECTOR_COUNT);
    for vector in list {
        let name = field(vector, "name");
        let body = unhex(field(vector, "body_hex"));
        let record = Record::from_name(field(vector, "record"))
            .unwrap_or_else(|| panic!("{name}: unknown record name"));

        let item = canon::decode(&body).unwrap_or_else(|error| panic!("{name}: {error}"));
        assert_eq!(
            canon::encode(&item).expect("re-encode"),
            body,
            "{name}: canonical re-encoding differs from the frozen bytes"
        );

        let result = if record == Record::BatchSignature {
            profile::validate_batch_signature_record(&body, &unhex(field(vector, "preimage_hex")))
        } else {
            profile::validate_record(record, &body)
        };
        result.unwrap_or_else(|error| panic!("{name}: {error}"));
    }
}

#[test]
fn digests_rederive_from_the_frozen_layouts() {
    let vectors = load("vectors.json");
    let mut checked = 0usize;
    for vector in entries(&vectors, "vectors") {
        let name = field(vector, "name");
        let body = unhex(field(vector, "body_hex"));
        let digests = &vector["digests"];
        let expected = |key: &str| field(digests, key);
        match field(vector, "record") {
            "batch_body" => {
                assert_eq!(
                    hex(profile::batch_id(&body).as_bytes()),
                    expected("batch_id"),
                    "{name}"
                );
                checked += 1;
            }
            "frontier" => {
                assert_eq!(
                    hex(profile::version_id(&body).as_bytes()),
                    expected("version_id"),
                    "{name}"
                );
                checked += 1;
            }
            "artifact_manifest" => {
                assert_eq!(
                    hex(profile::artifact_id(&body).as_bytes()),
                    expected("artifact_id"),
                    "{name}"
                );
                checked += 1;
            }
            "epoch_descriptor" => {
                assert_eq!(
                    hex(profile::epoch_id(&body).as_bytes()),
                    expected("epoch_id"),
                    "{name}"
                );
                checked += 1;
            }
            "conflict" => {
                assert_eq!(
                    hex(profile::conflict_id(&body).as_bytes()),
                    expected("conflict_id"),
                    "{name}"
                );
                checked += 1;
            }
            "branch_descriptor" => {
                assert_eq!(
                    hex(&profile::branch_descriptor_id(&body)),
                    expected("branch_descriptor_id"),
                    "{name}"
                );
                checked += 1;
            }
            "semantic_manifest" => {
                assert_eq!(
                    hex(&profile::semantic_manifest_id(&body)),
                    expected("semantic_manifest_id"),
                    "{name}"
                );
                checked += 1;
            }
            _ => {}
        }
    }
    assert_eq!(
        checked, 14,
        "expected every digest-bearing vector to be checked"
    );
}

#[test]
fn artifact_payload_digests_rederive() {
    let vectors = load("vectors.json");
    let payloads: [(&str, &str, &[u8]); 2] = [
        (
            "artifact/text-baseline",
            "text-baseline-v1",
            b"PuyuDB canonical vector",
        ),
        ("artifact/empty", "text-baseline-v1", b""),
    ];
    for (name, kind, payload) in payloads {
        let vector = entries(&vectors, "vectors")
            .iter()
            .find(|candidate| field(candidate, "name") == name)
            .unwrap_or_else(|| panic!("{name} vector is missing"));
        let manifest = profile::ArtifactManifest::for_payload(kind, payload).expect("manifest");
        assert_eq!(
            hex(&manifest.encode().expect("encode")),
            field(vector, "body_hex"),
            "{name}"
        );
        assert_eq!(
            hex(&profile::raw_digest(kind, payload)),
            field(&vector["digests"], "raw_digest"),
            "{name}"
        );
        let chunks: Vec<String> = manifest
            .chunks
            .iter()
            .map(|chunk| hex(chunk.as_bytes()))
            .collect();
        let expected: Vec<String> = vector["digests"]["chunk_ids"]
            .as_array()
            .expect("chunk ids")
            .iter()
            .map(|value| value.as_str().expect("chunk id").to_owned())
            .collect();
        assert_eq!(chunks, expected, "{name}");
    }
}

#[test]
fn signatures_reproduce_the_python_fixture_bytes() {
    let vectors = load("vectors.json");
    let seed: [u8; 32] = fixture_bytes("signing-seed", 32).try_into().expect("seed");
    assert_eq!(hex(&profile::public_key(&seed)), {
        let signature_vector = entries(&vectors, "vectors")
            .iter()
            .find(|candidate| field(candidate, "name") == "batch/signature")
            .expect("signature vector");
        field(signature_vector, "public_key_hex").to_owned()
    });

    for vector in entries(&vectors, "vectors") {
        let name = field(vector, "name");
        if name != "batch/signature" && name != "branch/envelope" {
            continue;
        }
        let preimage = unhex(field(vector, "preimage_hex"));
        let signature = unhex(field(vector, "signature_hex"));
        assert_eq!(signature.len(), 64, "{name}");
        match name {
            "batch/signature" => {
                let domain = b"puyudb/signature/v1";
                assert!(preimage.starts_with(domain), "{name}: wrong domain");
                let space =
                    SpaceId::from_bytes(&preimage[domain.len() + 1..][..16]).expect("space");
                let batch = preimage[preimage.len() - 32..].to_vec();
                let mut batch_id = [0u8; 32];
                batch_id.copy_from_slice(&batch);
                let batch = BatchId::from_array(batch_id);
                let reproduced = profile::sign_batch(&seed, &space, &batch);
                assert_eq!(
                    hex(&reproduced),
                    hex(&signature),
                    "{name}: signature differs"
                );
                profile::verify_batch_signature(
                    &profile::public_key(&seed),
                    &space,
                    &batch,
                    &reproduced,
                )
                .expect("verify");
            }
            _ => {
                let frontier_vector = entries(&vectors, "vectors")
                    .iter()
                    .find(|candidate| field(candidate, "name") == "frontier/two-heads")
                    .expect("frontier vector");
                let initial_version =
                    profile::version_id(&unhex(field(frontier_vector, "body_hex")));
                let descriptor = profile::BranchDescriptor {
                    space: SpaceId::from_bytes(&fixture_bytes("space", 16)).expect("space"),
                    branch: BranchId::from_bytes(&fixture_bytes("branch", 16)).expect("branch"),
                    initial_version,
                    creator: profile::public_key(&seed),
                };
                let body = descriptor.encode().expect("descriptor");
                assert_eq!(
                    hex(&profile::branch_signature_preimage(&body)),
                    hex(&preimage),
                    "{name}"
                );
                let reproduced = profile::sign_branch_descriptor(&seed, &body);
                assert_eq!(
                    hex(&reproduced),
                    hex(&signature),
                    "{name}: signature differs"
                );
            }
        }
    }
}

#[test]
fn actor_names_match_the_python_fixture() {
    let epoch = EpochId::from_bytes(&fixture_bytes("epoch", 32)).expect("epoch");
    let branch = BranchId::from_bytes(&fixture_bytes("branch", 16)).expect("branch");
    let writer_epoch =
        WriterEpoch::from_bytes(&fixture_bytes("writer-epoch", 16)).expect("writer epoch");
    let seed: [u8; 32] = fixture_bytes("signing-seed", 32).try_into().expect("seed");
    let public_key = profile::public_key(&seed);
    assert_eq!(
        profile::seed_actor_name(&epoch),
        "s:c_YvYXW18fQ2Iibsk_BtqVNIsicmchegnYlyr_my_5Y"
    );
    assert_eq!(
        profile::writer_actor_name(&public_key, &branch, &writer_epoch, &epoch),
        "w:ntACkklc9D0_PDozKdA6fiYklNXOODKTndwV9kgVuTk"
    );
    assert_eq!(
        hex(&profile::public_key(&seed)),
        "bc3eb9d607261a6998caef8808e8dbd4ba83a29b373f44808334860217c088a2"
    );
}

#[test]
fn every_negative_case_fails_with_its_declared_code() {
    let corpus = load("negative.json");
    let cases = entries(&corpus, "cases");
    assert!(
        cases.len() >= MIN_NEGATIVE_CASES,
        "corpus shrank to {} cases",
        cases.len()
    );
    for case in cases {
        let name = field(case, "name");
        let body = unhex(field(case, "body_hex"));
        let expected = field(case, "code");
        let record = Record::from_name(field(case, "record"))
            .unwrap_or_else(|| panic!("{name}: unknown record name"));
        let result = if record == Record::BatchSignature {
            profile::validate_batch_signature_record(&body, &unhex(field(case, "preimage_hex")))
        } else {
            profile::validate_record(record, &body)
        };
        match result {
            Ok(()) => panic!("{name}: accepted input that must be rejected as {expected}"),
            Err(error) => assert_eq!(
                error.code(),
                expected,
                "{name}: reported {error} instead of {expected}"
            ),
        }
    }
    let codes: std::collections::BTreeSet<&str> =
        cases.iter().map(|case| field(case, "code")).collect();
    assert_eq!(
        codes,
        [
            "hash_mismatch",
            "invalid_encoding",
            "invalid_signature",
            "unsupported_capability",
            "unsupported_version"
        ]
        .into_iter()
        .collect(),
        "the corpus must cover every assigned error code"
    );
}

#[test]
fn path_cases_agree() {
    let corpus = load("negative.json");
    let cases = entries(&corpus, "path_cases");
    assert!(cases.len() >= MIN_PATH_CASES);
    for case in cases {
        let name = field(case, "name");
        let value = field(case, "value");
        let accepted = case["accepted"].as_bool().expect("accepted is a bool");
        assert_eq!(Path::new(value).is_ok(), accepted, "{name}: {value}");
    }
}

#[test]
fn artifact_ids_bind_the_epoch_even_for_empty_payloads() {
    let first = profile::NativeArtifact {
        epoch: EpochId::from_array([1; 32]),
        profile: profile::TEXT_PROFILE.to_owned(),
        native: Vec::new(),
    };
    let second = profile::NativeArtifact {
        epoch: EpochId::from_array([2; 32]),
        ..first.clone()
    };
    let id = |artifact: &profile::NativeArtifact| {
        let payload = artifact.encode().expect("payload");
        profile::ArtifactManifest::for_payload("native-change-v1", &payload)
            .expect("manifest")
            .id()
            .expect("id")
    };
    assert!(first.native.is_empty());
    assert_ne!(id(&first), id(&second));
    assert_ne!(
        profile::seed_actor_name(&first.epoch),
        profile::seed_actor_name(&second.epoch)
    );
}

#[test]
fn unknown_record_names_are_programming_errors() {
    assert!(Record::from_name("not_a_record").is_none());
    let mut artifact = [0u8; 32];
    artifact[0] = 1;
    let id = ArtifactId::from_array(artifact);
    assert_eq!(id.as_bytes()[0], 1);
}
